import re

# For each dialog, let's separate agent messages from customer messages
# and check for apology keywords in agent messages

def get_agent_messages(dialog_text, company_id):
    """Extract messages from the support agent."""
    lines = dialog_text.split('\n\n')
    agent_messages = []
    for line in lines:
        if line.startswith(company_id):
            agent_messages.append(line)
    return agent_messages

def has_apology(agent_messages):
    """Check if any agent message contains an apology."""
    apology_patterns = re.compile(r'\b(sorry|apologize|apologies|apology|apologise)\b', re.IGNORECASE)
    for msg in agent_messages:
        if apology_patterns.search(msg):
            return True
    return False

def get_customer_messages(dialog_text, company_id):
    """Extract customer messages."""
    lines = dialog_text.split('\n\n')
    customer_messages = []
    for line in lines:
        if not line.startswith(company_id) and line.strip():
            customer_messages.append(line)
    return customer_messages

